"""Validate incidents.csv against schema v0.1. Usage: python validate.py incidents.csv"""
import csv
import re
import sys
from datetime import date

COLUMNS = ["id", "date_occurred", "date_disclosed", "developer", "system", "system_type",
           "capability", "harm_type", "severity", "detection", "response", "sources", "coder", "notes"]
ENUMS = {
    "system_type": {"frontier-LLM", "agent", "image", "other"},
    "harm_type": {"none-near-miss", "privacy", "financial", "physical", "security", "societal"},
    "severity": {"0", "1", "2", "3", "4"},
    "detection": {"internal-eval", "red-team", "user-report", "journalist", "researcher"},
    "response": {"patched", "withdrawn", "disputed", "none"},
}


def check(path):
    errors = []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames != COLUMNS:
            return [f"header mismatch: {reader.fieldnames}"]
        seen = set()
        for n, row in enumerate(reader, start=2):
            if not re.fullmatch(r"IW-\d{4}-\d{3}", row["id"]):
                errors.append(f"line {n}: bad id {row['id']!r}")
            if row["id"] in seen:
                errors.append(f"line {n}: duplicate id {row['id']}")
            seen.add(row["id"])
            for col in ("date_occurred", "date_disclosed"):
                try:
                    date.fromisoformat(row[col])
                except ValueError:
                    errors.append(f"line {n}: bad {col} {row[col]!r}")
            for col, allowed in ENUMS.items():
                if row[col] not in allowed:
                    errors.append(f"line {n}: {col}={row[col]!r} not in {sorted(allowed)}")
            if not row["sources"].strip():
                errors.append(f"line {n}: no sources")
    return errors


if __name__ == "__main__":
    errs = check(sys.argv[1] if len(sys.argv) > 1 else "incidents.csv")
    print("\n".join(errs) if errs else "OK")
    sys.exit(1 if errs else 0)
